#!/bin/bash
set -e
APP=/root/opslabs
ts=$(date +%Y%m%d-%H%M%S)
mkdir -p "$APP/app/licenses"
cp "$APP/app/licenses/models.py" "$APP/app/licenses/models.py.bak.$ts" 2>/dev/null || true

echo "=== diagnostic: any other Role class definitions on this server? ==="
grep -rn "class Role" "$APP/app" || echo "(only one found, or grep found nothing)"

base64 -d << 'LICMODELS_B64' > "$APP/app/licenses/models.py"

LICMODELS_B64

python3 -m py_compile "$APP/app/licenses/models.py"
systemctl restart opslabs-app.service
sleep 2
systemctl status opslabs-app.service --no-pager -l | head -15
journalctl -u opslabs-app.service -n 20 --no-pager
